              ` origin=${HelpersTaon.git.getOriginURL(cwd, origin)}`,
          );
          Helpers.run(command, { cwd }).sync();
          Helpers.info(taskName);
          break;
        } catch (err) {
          Helpers.error(
            `[taon-helpers] Not able to push branch ${currentBranchName} in (origin=${origin}):
        ${cwd}`,
            true,
            true,
          );
          if (!askToRetry) {
            return false;
          }
          const pushOptions = {
            normal: {
              name: 'Try normal push again ?',
            },
            normalButSshOrHttpOrigin: {
              name: `Try normal ${isSsh ? 'HTTPS' : 'SSH'} origin push again ?`,
            },
            force: {
              name: 'Try again with force push ?',
            },
            rebasePullAndPush: {
              name: 'Try abort git oper. + restet HEAD~10 + pull + normal push ?',
            },
            pulAndPush: {
              name: 'Try pull and then push ?',
            },
            skip: {
              name: 'Skip pushing',
            },
            openInVscode: {
              name: 'Open in vscode window',
            },
            exit: {
              name: 'Exit process',
            },
          };
          const whatToDo = await UtilsTerminal.select<keyof typeof pushOptions>(
            {
              question: 'What to do ?',
              choices: pushOptions,
            },
          );
          if (whatToDo === 'normalButSshOrHttpOrigin') {
            if (isSsh) {
              await HelpersTaon.git.changeRemoveFromSshToHttps(cwd);
            } else {
              await HelpersTaon.git.changeRemoteFromHttpsToSSh(cwd);
            }
          }
          if (whatToDo === 'pulAndPush') {
            await HelpersTaon.git.pullCurrentBranch(cwd, {
              askToRetry,
              exitOnError: false,
            });
            continue;
          }

          if (whatToDo === 'rebasePullAndPush') {
            abortAllGitTemporaryOperations(cwd);
            resetHard(cwd, {
              HEAD: 10,
            });
            await HelpersTaon.git.pullCurrentBranch(cwd, {
              askToRetry,
              exitOnError: false,
            });
            continue;
          }
          if (whatToDo === 'openInVscode') {
            try {
              await UtilsVSCode.openFolder(cwd);
            } catch (error) {}
            continue;
          }
          if (whatToDo === 'skip') {
            return false;
          }
          if (whatToDo === 'exit') {
            process.exit(0);
          }
          force = whatToDo === 'force';
          continue;
        }
      }
      return true;
    }

