      for (const entry of entries) {
        // Skip the .git directory
        if (entry === '.git') {
          continue;
        }
        const fullPath = crossPlatformPath([cwd, entry]);
        const stats = fse.statSync(fullPath);
        if (stats.isDirectory()) {
