async (
    pathToJsFile: string,
    outputFilePath: string,
    options?: {
      strategy?: 'cli' | 'vscode-ext' | 'node-app' | 'electron-app';
      /**
       * ! beforeWrite needs to return output
       */
      beforeWrite?: (options: {
        output?: string;
        copyToDestination?: (fileOrFolderAbsPath: string) => void;
      }) => string;
      additionalExternals?: string[];
      additionalReplaceWithNothing?: string[];
      skipFixingSQLlite?: boolean;
      minify?: boolean;
      /**
       * TODO
       */
      prod?: boolean;
      useTsConfig?: boolean;
      format?: BuildOptions['format'];
      target?: BuildOptions['target'];
    },
  ): Promise<void> => {
    //#region @backendFunc
    let {
      beforeWrite,
      additionalExternals,
      additionalReplaceWithNothing,
      skipFixingSQLlite,
      minify,
      prod,
      strategy,
      useTsConfig,
      format,
      target,
    } = options || {};
    if (!strategy) {
      strategy = 'cli';
    }
    if (!format) {
      format = 'cjs';
    }

    if (!target) {
      target = 'node20';
    }

    Helpers.info(`Bundling to single file (strategy = ${strategy})
       ${pathToJsFile}
       to
        ${outputFilePath}
       `);
    let replaceWithNothing = Utils.uniqArray([
      'esbuild',
      ...(additionalReplaceWithNothing || []),
    ]);
    let externals = Utils.uniqArray([
      'esbuild',
      'electron',
      'vscode',
      'ts-node',
      // 'webpack',
