src/lib/utils.ts#UtilsHttpServer.start.value:
async (
    cwd: string,
    port: number,
    options?: {
      startMessage?: string;
      resoveWhenStarted?: boolean;
    },
  ) => {
    //#region @backendFunc
    options = options || {};
    const express = require('express');
    const app = express();

    // Serve static files from the provided cwd
    app.use(express.static(cwd));

    // Catch-all to handle any invalid routes (404 errors)
    app.use((req, res) => {
      res.status(404).send('File not found');
    });

    Helpers.taskStarted(`Starting server.. http://localhost:${port}`);
    // Start the server

    if (options.resoveWhenStarted) {
      return await new Promise<void>((resolve, reject) => {
        // Handle Ctrl+C (SIGINT) gracefully
        const server = app.listen(port, () => {
          Helpers.taskDone(
            options.startMessage ||
              `Server started at http://localhost:${port}, serving files from ${cwd}`,
          );
          process.on('SIGINT', () => {
            server.close(() => resolve());
          });
          resolve();
        });
      });
    }

    const server = app.listen(port, () => {
      Helpers.taskDone(
        options.startMessage ||
          `Server started at http://localhost:${port}, serving files from ${cwd}`,
      );
    });

    return await new Promise<void>((resolve, reject) => {
      // Handle Ctrl+C (SIGINT) gracefully
      process.on('SIGINT', () => {
        server.close(() => resolve());
      });
    });
    //#endregion
  }

