async (password: string): Promise<string> => {
    //#region @backendFunc
    const salt = crypto.getRandomValues(new Uint8Array(SALT_LENGTH));

    const hash = await deriveKey(password, salt, ITERATIONS);

    return [
      'pbkdf2',
      'sha256',
      ITERATIONS,
      toBase64(salt),
      toBase64(hash),
    ].join('$');
    //#endregion
  }

src/lib/utils.ts#UtilsPasswords.verifyPa.value:
async (
    password: string,
    stored: string,
  ): Promise<boolean> => {
    //#region @backendFunc
    try {
      const [
        algorithm,
        hashAlgorithm,
        iterationsString,
        saltBase64,
        hashBase64,
      ] = stored.split('$');

      if (algorithm !== 'pbkdf2' || hashAlgorithm !== 'sha256') {
        return false;
      }

      const iterations = Number(iterationsString);

      if (
        !Number.isSafeInteger(iterations) ||
        iterations <= 0 ||
        !saltBase64 ||
        !hashBase64
      ) {
        return false;
      }

      const salt = fromBase64(saltBase64);
      const expectedHash = fromBase64(hashBase64);

      const actualHash = await deriveKey(password, salt, iterations);

      return timingSafeEqual(expectedHash, actualHash);
    } catch {
      return false;
    }
    //#endregion
  }

